static UINT     test_failures;
static ULONG    test_checks;


/* Record the outcome of one expectation.  */
static VOID  test_expect(const char *description, ULONG actual, ULONG expected)
{
    test_checks++;

    if (actual != expected)
    {
        printf("FAIL: %s (expected %lu, got %lu)\n", description, (unsigned long) expected, (unsigned long) actual);
        test_failures++;
    }
}


/* The protection mutex. It counts its owner, and counts a release by a caller that
   does not hold it, which the real mutex refuses with TX_NOT_OWNED.  */

static ULONG    test_mutex_depth;
static ULONG    test_mutex_unowned_puts;

UINT  _tx_mutex_get(TX_MUTEX *mutex_ptr, ULONG wait_option)
{
    (VOID) mutex_ptr;
    (VOID) wait_option;

    test_mutex_depth++;

    return(TX_SUCCESS);
}

UINT  _tx_mutex_put(TX_MUTEX *mutex_ptr)
{

UINT    status;


    (VOID) mutex_ptr;

    if (test_mutex_depth == ((ULONG) 0))
    {
        test_mutex_unowned_puts++;
        status =  TX_NOT_OWNED;
    }
    else
    {
        test_mutex_depth--;
        status =  TX_SUCCESS;
    }

    return(status);
}


/* The byte pool the loaders allocate code and data from: a bump allocator over a
   static arena, which can be told to refuse.  */

#define TEST_POOL_BYTES     ((ULONG) 8192)

static union
{
    ALIGN_TYPE  test_pool_alignment;
    UCHAR       test_pool_bytes[TEST_POOL_BYTES];
} test_pool;

static ULONG    test_pool_offset;
static ULONG    test_allocations;
static ULONG    test_releases;
static UINT     test_allocate_refuse;

UINT  _tx_byte_allocate(TX_BYTE_POOL *pool_ptr, VOID **memory_ptr, ULONG memory_size, ULONG wait_option)
{

ULONG   rounded_size;
UINT    status;


    (VOID) pool_ptr;
    (VOID) wait_option;

    rounded_size =  ((memory_size + ((ULONG) 7)) / ((ULONG) 8)) * ((ULONG) 8);

    if ((test_allocate_refuse != TX_FALSE) || (rounded_size > (TEST_POOL_BYTES - test_pool_offset)))
    {
        status =  TX_NO_MEMORY;
    }
    else
    {
        *memory_ptr =  (VOID *) &test_pool.test_pool_bytes[test_pool_offset];
        test_pool_offset =  test_pool_offset + rounded_size;
        test_allocations++;
        status =  TX_SUCCESS;
    }

    return(status);
}

UINT  _tx_byte_release(VOID *memory_ptr)
{
    (VOID) memory_ptr;

    test_releases++;

    return(TX_SUCCESS);
}


